uniform vec4 u_scale;
uniform vec4 u_translate;
uniform vec4 u_innerscale;
uniform vec4 u_innertranslate;

vec4 st_transform_map(vec4 pos) {
    return vec4((pos.xyz * u_innerscale.xyz + u_innertranslate.xyz * pos.w).xyz
                 * u_scale.xyz + u_translate.xyz * pos.w, pos.w);
}


vec4 transform_map_chain(vec4 pos) {
    vec4 result_1 = st_transform_map(pos);
    return result_1;
}

vec4 transform_map_chain_1(vec4 pos) {
    vec4 result_1 = transform_map_chain(pos);
    return result_1;
}

