uniform sampler3D u_volumetex_15;
uniform sampler3D dummy1;
float dummy;
uniform float u_weight_0;
uniform int u_enabled_0;

uniform vec3 u_shape;
uniform float u_downsample;
uniform vec4 u_bgcolor;

uniform vec3 u_clip_min;
uniform vec3 u_clip_max;

//varyings
// varying vec3 v_texcoord;
varying vec3 v_position;
varying vec4 v_nearpos;
varying vec4 v_farpos;

// uniforms for lighting. Hard coded until we figure out how to do lights
const vec4 u_ambient = vec4(0.2, 0.4, 0.2, 1.0);
const vec4 u_diffuse = vec4(0.8, 0.2, 0.2, 1.0);
const vec4 u_specular = vec4(1.0, 1.0, 1.0, 1.0);
const float u_shininess = 40.0;

//varying vec3 lightDirs[1];

// global holding view direction in local coordinates
vec3 view_ray;


// for some reason, this has to be the last function in order for the
// filters to be inserted in the correct place...

float rand(vec3 co) {
    float a = 12.9898;
    float b = 78.233;
    float c = 43758.5453;
    float dt= dot(vec2(co.x, co.y + co.z) ,vec2(a,b));
    float sn= mod(dt,3.14);
    return fract(sin(sn) * c);
}

void main() {
    clip();


    vec3 farpos = v_farpos.xyz / v_farpos.w;
    vec3 nearpos = v_nearpos.xyz / v_nearpos.w;

    // Calculate unit vector pointing in the view direction through this
    // fragment.
    view_ray = normalize(farpos.xyz - nearpos.xyz);

    // Compute the distance to the front surface or near clipping plane
    float distance = dot(nearpos-v_position, view_ray);
    distance = max(distance, min((-0.5 - v_position.x) / view_ray.x,
                            (u_shape.x - 0.5 - v_position.x) / view_ray.x));
    distance = max(distance, min((-0.5 - v_position.y) / view_ray.y,
                            (u_shape.y - 0.5 - v_position.y) / view_ray.y));
    distance = max(distance, min((-0.5 - v_position.z) / view_ray.z,
                            (u_shape.z - 0.5 - v_position.z) / view_ray.z));

    // Now we have the starting position on the front surface
    vec3 front = v_position + view_ray * distance;

    // Decide how many steps to take
    int nsteps = int(-distance / u_downsample + 0.5);
    if(nsteps < 1) discard;

    // Get starting location and step vector in texture coordinates
    vec3 step = ((v_position - front) / u_shape) / nsteps;
    vec3 start_loc = front / u_shape;

    float val;

    // This outer loop seems necessary on some systems for large
    // datasets. Ugly, but it works ...
    vec3 loc = start_loc;
    int iter = 0;

    dummy = texture3D(u_volumetex_0, loc).g;
    dummy = texture3D(u_volumetex_1, loc).g;
    dummy = texture3D(u_volumetex_2, loc).g;
    dummy = texture3D(u_volumetex_3, loc).g;
    dummy = texture3D(u_volumetex_4, loc).g;
    dummy = texture3D(u_volumetex_5, loc).g;
    dummy = texture3D(u_volumetex_6, loc).g;
    dummy = texture3D(u_volumetex_7, loc).g;
    dummy = texture3D(u_volumetex_8, loc).g;
    dummy = texture3D(u_volumetex_9, loc).g;
    dummy = texture3D(u_volumetex_10, loc).g;
    dummy = texture3D(u_volumetex_11, loc).g;
    dummy = texture3D(u_volumetex_12, loc).g;
    dummy = texture3D(u_volumetex_13, loc).g;
    dummy = texture3D(u_volumetex_14, loc).g;
    dummy = texture3D(u_volumetex_15, loc).g;
    float max_val_0 = 0;

    // We avoid putting this if statement in the loop for performance

    if (u_downsample > 1.) {

        // In the case where we are downsampling we use a step size that is
        // random to avoid artifacts in the output. This appears to be fast
        // enough to still make the downsampling worth it.

        while (iter < nsteps) {
            for (iter=iter; iter<nsteps; iter++)
            {

                if(u_enabled_0 == 1) {

                if(loc.r > u_clip_min.r && loc.r < u_clip_max.r &&
                   loc.g > u_clip_min.g && loc.g < u_clip_max.g &&
                   loc.b > u_clip_min.b && loc.b < u_clip_max.b) {

                // Sample texture for layer f7383a17-aaff-4876-8eb5-65c1abf2eee3
                val = texture3D(u_volumetex_0, loc).g;
                max_val_0 = max(val, max_val_0);

                }

                }

                // Advance location deeper into the volume
                loc += (0.5 + rand(loc)) * step;

            }
        }

    } else {

        while (iter < nsteps) {
            for (iter=iter; iter<nsteps; iter++)
            {

                if(u_enabled_0 == 1) {

                if(loc.r > u_clip_min.r && loc.r < u_clip_max.r &&
                   loc.g > u_clip_min.g && loc.g < u_clip_max.g &&
                   loc.b > u_clip_min.b && loc.b < u_clip_max.b) {

                // Sample texture for layer f7383a17-aaff-4876-8eb5-65c1abf2eee3
                val = texture3D(u_volumetex_0, loc).g;
                max_val_0 = max(val, max_val_0);

                }

                }

                // Advance location deeper into the volume
                loc += step;

            }
        }

    }


    float count = 0;
    vec4 color = vec4(0., 0., 0., 0.);
    vec4 total_color = vec4(0., 0., 0., 0.);
    float max_alpha = 0;

    // Compute final color for layer f7383a17-aaff-4876-8eb5-65c1abf2eee3
    color = translucent_fire(max_val_0);
    color.a *= u_weight_0;
    total_color += color.a * color;
    max_alpha = max(color.a, max_alpha);
    count += color.a;

    if(count > 0) {

        total_color /= count;
        total_color.a = max_alpha;

        // Due to issues with transparency in Qt5, we need to convert the color
        // to a flattened version without transparency, so we do alpha blending
        // with the background and set alpha to 1:
        total_color.r = total_color.r * total_color.a + u_bgcolor.r * (1 - total_color.a);
        total_color.g = total_color.g * total_color.a + u_bgcolor.g * (1 - total_color.a);
        total_color.b = total_color.b * total_color.a + u_bgcolor.b * (1 - total_color.a);
        total_color.a = 1.;

    } else {

        // For this it seems we can get away with using transparency (which we need
        // to make sure axes/ticks/labels aren't hidden)
        total_color = vec4(0, 0, 0, 0);

    }

    gl_FragColor = total_color;

    /* Set depth value - from visvis TODO
